import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);
  assert.deepEqual(r.value.lines[0], {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 5,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 5,
  });
  assert.deepEqual(r.value.lines[1], {
    sku: 'LOGO-PACK',
    name: 'Logo package',
    qty: 1,
    unitPrice: 120000,
    vatRate: 21,
    discountPercent: 5,
  });
});

test('createInvoice returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-999',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' }
  );
});

